// OnConflict allows configuring the `ON CONFLICT` / `ON DUPLICATE KEY` clause
// of the `INSERT` statement. For example:
//
//	client.ConduitSession.CreateBulk(builders...).
//		OnConflict(
//			// Update the row with the new values
//			// the was proposed for insertion.
//			sql.ResolveWithNewValues(),
//		).
//		// Override some of the fields with custom
//		// update values.
//		Update(func(u *ent.ConduitSessionUpsert) {
//			SetPrincipalKind(v+v).
//		}).
//		Exec(ctx)
func (_c *ConduitSessionCreateBulk) OnConflict(opts ...sql.ConflictOption) *ConduitSessionUpsertBulk {
	_c.conflict = opts
	return &ConduitSessionUpsertBulk{
		create: _c,
	}
}

// OnConflictColumns calls `OnConflict` and configures the columns
// as conflict target. Using this option is equivalent to using:
//
//	client.ConduitSession.Create().
//		OnConflict(sql.ConflictColumns(columns...)).
//		Exec(ctx)
func (_c *ConduitSessionCreateBulk) OnConflictColumns(columns ...string) *ConduitSessionUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &ConduitSessionUpsertBulk{
		create: _c,
	}
}

// ConduitSessionUpsertBulk is the builder for "upsert"-ing
// a bulk of ConduitSession nodes.
type ConduitSessionUpsertBulk struct {
	create *ConduitSessionCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.ConduitSession.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(conduitsession.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *ConduitSessionUpsertBulk) UpdateNewValues() *ConduitSessionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(conduitsession.FieldID)
			}
			if _, exists := b.mutation.PrincipalKind(); exists {
				s.SetIgnore(conduitsession.FieldPrincipalKind)
			}
			if _, exists := b.mutation.PrincipalID(); exists {
				s.SetIgnore(conduitsession.FieldPrincipalID)
			}
			if _, exists := b.mutation.ProjectID(); exists {
				s.SetIgnore(conduitsession.FieldProjectID)
			}
			if _, exists := b.mutation.RelayInstanceID(); exists {
				s.SetIgnore(conduitsession.FieldRelayInstanceID)
			}
			if _, exists := b.mutation.RelayGeneration(); exists {
				s.SetIgnore(conduitsession.FieldRelayGeneration)
			}
			if _, exists := b.mutation.Transport(); exists {
				s.SetIgnore(conduitsession.FieldTransport)
			}
			if _, exists := b.mutation.EndpointIncarnation(); exists {
				s.SetIgnore(conduitsession.FieldEndpointIncarnation)
			}
			if _, exists := b.mutation.ExecScope(); exists {
				s.SetIgnore(conduitsession.FieldExecScope)
			}
			if _, exists := b.mutation.ConnectionEpoch(); exists {
				s.SetIgnore(conduitsession.FieldConnectionEpoch)
			}
			if _, exists := b.mutation.ConnectedAt(); exists {
				s.SetIgnore(conduitsession.FieldConnectedAt)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.ConduitSession.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *ConduitSessionUpsertBulk) Ignore() *ConduitSessionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *ConduitSessionUpsertBulk) DoNothing() *ConduitSessionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the ConduitSessionCreateBulk.OnConflict
// documentation for more info.
func (u *ConduitSessionUpsertBulk) Update(set func(*ConduitSessionUpsert)) *ConduitSessionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&ConduitSessionUpsert{UpdateSet: update})
	}))
	return u
}

